use vstd::prelude::*;

verus! {
    // Concatenate two vectors of f32, returning a new vector res such that
    // 1. res.len() == a.len() + b.len()
    // 2. ∀ i < a.len(): res[i] == a[i]
    // 3. ∀ j < b.len(): res[a.len() + j] == b[j]
    fn concatenate(a: Vec<f32>, b: Vec<f32>) -> (res: Vec<f32>)
        ensures
            res.len() == a.len() + b.len(),
            forall|i: usize| i < a.len() ==> res[i] == a[i],
            forall|j: usize| j < b.len() ==> res[a.len() + j] == b[j],
    {
        let mut res: Vec<f32> = Vec::new();
        let la = a.len();
        let lb = b.len();

        // First loop: copy all elements of a
        let mut i: usize = 0;
        while i < la
            invariant
                i <= la,
                res.len() == i,
                forall|k: usize| k < i ==> res[k] == a[k],
            decreases la - i,
        {
            res.push(a[i]);
            i += 1;
        }

        // Second loop: copy all elements of b
        let mut j: usize = 0;
        while j < lb
            invariant
                j <= lb,
                res.len() == la + j,
                // a’s part remains correct
                forall|k: usize| k < la ==> res[k] == a[k],
                // b’s part up to j is correct
                forall|k: usize| k < j ==> res[la + k] == b[k],
            decreases lb - j,
        {
            res.push(b[j]);
            j += 1;
        }

        res
    }
}

fn main() {
    // Example usage (not verified):
    let a = vec![1.0f32, 2.0, 3.0];
    let b = vec![4.0f32, 5.0];
    let c = concatenate(a.clone(), b.clone());
    assert!(c.len() == a.len() + b.len());
    for i in 0..a.len() {
        assert!(c[i] == a[i]);
    }
    for j in 0..b.len() {
        assert!(c[a.len() + j] == b[j]);
    }
}